// One webhook, two platforms. Logzz is the pay-on-delivery scheduling and its field
// names below are CONFIRMED — read off a real payload from the panel's own Testar button
// on 2026-09-09. Coinzz is still expected, not confirmed; the first real one that fails
// arrives as an e-mail with the raw JSON, which is how this half gets confirmed too.
//
// Nothing here reaches past those names. What does not resolve leaves ok:false and goes
// to the operator raw, because a half-filled order files the wrong sale against the wrong
// woman and the post-order ruler then chases her for it.
const item = $input.first().json;
const body = item.body ?? item;
const query = item.query ?? {};
const fonte = String(query.fonte ?? '').toLowerCase();

const at = (obj, path) => path.split('.').reduce((o, k) => (o == null ? undefined : o[k]), obj);
const pick = (paths) => {
  for (const p of paths) {
    const v = at(body, p);
    if (v !== undefined && v !== null && String(v).trim() !== '') return v;
  }
  return undefined;
};

// Logzz sends both: `external_id` is its own sale id ("venq000x10") and `order_number`
// the composite the panel shows. The sale id goes first because it is the one that is
// unambiguously one row; the order number is the fallback and what a human recognises.
const externalId = pick(['external_id', 'order_number', 'id', 'order_id', 'orderId', 'transaction_id', 'sale_id', 'code', 'codigo', 'order.id', 'data.id']);
const phoneRaw = pick(['client_phone', 'phone', 'telefone', 'celular', 'whatsapp', 'customer.phone', 'customer.telefone', 'cliente.telefone', 'buyer.phone', 'data.customer.phone']);
// The order total, not the unit price: `products.main.sale_price` is per unit and the
// quantity can be more than one. She pays `order_final_price`.
const amountRaw = pick(['order_final_price', 'amount', 'value', 'valor', 'total', 'price', 'order.total', 'data.amount']);

// The size has no field of its own. The Logzz page has no size selector, so the
// supplier's instruction — in uppercase, in the product description — tells her to type
// it into the COMPLEMENT of the scheduling, which arrives as `client_address_comp`.
//
// One size token in there wins. Zero is a blank complement or a real one ("Apt 101").
// Two is "P ou M?", which is a coin toss, and the loser gets the wrong garment. Both go
// to the operator instead of being guessed.
const SIZES = ['XGG', 'GGG', 'GG', 'P', 'M', 'G'];
const explicito = String(pick(['size', 'tamanho', 'variant', 'variacao', 'variation']) ?? '').toUpperCase().replace(/[^A-Z]/g, '');
const complemento = String(pick(['client_address_comp', 'complement', 'complemento', 'observacao', 'obs', 'notes', 'address.complement']) ?? '').toUpperCase();
//
// One trap that a probe caught before this went live: "Bloco B, apto G" read as a size G.
// A single letter is a size in "GG" and a flat number in "apto G", and the difference is
// the word before it. Two or more letters are never an address ("apto XGG" is nobody).
const ENDERECO = ['APTO', 'APT', 'AP', 'BLOCO', 'BL', 'CASA', 'CS', 'QUADRA', 'QD', 'LOTE', 'LT', 'TORRE', 'SALA', 'ANDAR', 'FUNDOS'];
const tokens = complemento.split(/[^A-Z]+/).filter(Boolean);
const achados = tokens.filter((t, i) => {
  if (!SIZES.includes(t)) return false;
  if (t.length > 1) return true;
  return !ENDERECO.includes(tokens[i - 1] ?? '');
});
const unico = achados.length === 1 ? achados[0] : undefined;
const size = SIZES.includes(explicito) ? explicito : unico;

// Logzz is the pay-on-delivery platform, Coinzz the prepaid one. The exception is a
// Coinzz order paid with `afterpay`, which IS pay on delivery (operator, 2026-09-08).
const declarado = String(pick(['payment_method', 'paymentMethod', 'forma_pagamento', 'payment.method']) ?? '').toLowerCase();
const paymentMethod = declarado === 'afterpay' ? 'cod' : (fonte === 'logzz' ? 'cod' : (fonte === 'coinzz' ? 'prepay' : undefined));

const phone = phoneRaw === undefined ? undefined : String(phoneRaw).replace(/\D/g, '');
const parseBrl = (v) => {
  if (v === undefined) return undefined;
  if (typeof v === 'number') return v;
  const s = String(v).replace(/[^\d.,-]/g, '');
  const norm = s.includes(',') ? s.replace(/\./g, '').replace(',', '.') : s;
  const n = Number(norm);
  return Number.isFinite(n) ? n : undefined;
};
const amountBrl = parseBrl(amountRaw);

// Logzz writes "2026-09-14 17:59:12" — a space, not a T, which is not ISO and only parses
// by luck. `scheduled_for` is a DATE column, so it takes the day and nothing else.
const soAData = (v) => (v === undefined ? null : String(v).slice(0, 10));
const paraIso = (v) => (v === undefined ? null : String(v).trim().replace(' ', 'T'));

const missing = [];
if (!externalId) missing.push('externalId');
if (!phone) missing.push('phone');
if (!size) missing.push(achados.length > 1 ? 'size (o complemento tem mais de um tamanho: ' + achados.join(', ') + ')' : 'size (nao achei P/M/G/GG/XGG no complemento)');
if (!paymentMethod) missing.push('paymentMethod (falta ?fonte=logzz ou ?fonte=coinzz na URL)');
if (!(amountBrl > 0)) missing.push('amountBrl');

const order = {
  externalId: externalId === undefined ? '' : String(externalId),
  phone,
  paymentMethod,
  size,
  amountBrl,
  status: pick(['order_status', 'status', 'situacao']) ?? 'created',
  checkoutUrl: pick(['checkout_url', 'checkoutUrl', 'url']) ?? null,
  scheduledFor: soAData(pick(['date_delivery', 'scheduled_for', 'delivery_date', 'data_entrega', 'agendamento'])),
  orderedAt: paraIso(pick(['date_order', 'created_at', 'ordered_at', 'date']))
};

return [{ json: { ok: missing.length === 0, missing: missing.join(', '), fonte: fonte || '(vazio)', order, raw: JSON.stringify(body, null, 2) } }];

